options.getOption:
// Sensors per WHO 2021 band of 24-hour PM2.5, in the map's colours: this is
// the map's legend too. Clicking a band filters the dashboard to it (the same
// variables the histogram's brush writes); clicking it again clears it.
const LO = 'pm_lo';
const HI = 'pm_hi';
const EDGES = [0, 15, 25, 37.5, 50, 75, 100];
const LABELS = ['≤ 15', '15–25', '25–37.5', '37.5–50', '50–75', '> 75'];
const COLORS = ['#4F8A9A', '#F2D16B', '#F0A04B', '#E5683C', '#C63A4A', '#8E2C6B'];

const chart = context.panel.chart;
const location = context.grafana.locationService;
const muted = context.grafana.theme.colors.text.secondary;

const frame = context.panel.data.series[0];
const counts = LABELS.map(() => 0);
if (frame) {
  const bands = frame.fields.find((f) => f.name === 'band').values;
  const ns = frame.fields.find((f) => f.name === 'n').values;
  Array.from(bands).forEach((b, i) => {
    counts[Number(b)] = Number(ns[i]);
  });
}
const total = counts.reduce((a, b) => a + b, 0) || 1;
const lo = context.grafana.replaceVariables('${' + LO + '}');
const hi = context.grafana.replaceVariables('${' + HI + '}');
const active = EDGES.slice(0, -1).findIndex((e, i) => String(e) === lo && String(EDGES[i + 1]) === hi);

chart.off('click');
chart.on('click', (event) => {
  const i = event.dataIndex;
  const same =
    String(EDGES[i]) === context.grafana.replaceVariables('${' + LO + '}') &&
    String(EDGES[i + 1]) === context.grafana.replaceVariables('${' + HI + '}');
  location.partial({ ['var-' + LO]: same ? '' : String(EDGES[i]), ['var-' + HI]: same ? '' : String(EDGES[i + 1]) }, true);
});

return {
  animation: false,
  grid: { left: 8, right: 16, top: 24, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (it) =>
      `${it.marker}<b>${LABELS[it.dataIndex]} µg/m³</b>${it.dataIndex === 0 ? ' · meets the WHO guideline' : ''}<br/>${counts[it.dataIndex]} sensors (${((100 * counts[it.dataIndex]) / total).toFixed(1)}%)`,
  },
  xAxis: { type: 'category', data: LABELS, axisTick: { show: false }, axisLabel: { color: muted, interval: 0, fontSize: 11 } },
  yAxis: { type: 'value', axisLabel: { color: muted }, splitLine: { lineStyle: { opacity: 0.15 } } },
  series: [
    {
      type: 'bar',
      barWidth: '80%',
      cursor: 'pointer',
      data: counts.map((n, i) => ({
        value: n,
        itemStyle: { color: COLORS[i], opacity: active >= 0 && active !== i ? 0.35 : 1, borderRadius: [4, 4, 0, 0] },
      })),
      label: { show: true, position: 'top', color: muted, formatter: (p) => `${((100 * p.value) / total).toFixed(0)}%` },
    },
  ],
};

// A histogram whose brush filters the rest of the dashboard.
//
// Dragging across it writes the selected range to two dashboard variables
// (LO and HI); the other panels filter on them, and this one does not, so it
// keeps showing the whole distribution the other filters leave. Two query
// frames feed it: `all` (grey, the context) and `selected` (colour, what the
// other filters leave). Each has columns `bin` (the bin's lower edge) and `n`.
//
// A dashboard changes only the constants block below.
// @constants begin
const LO = 'pm_lo';
const HI = 'pm_hi';
const STEP = 5;
const DOMAIN = [0, 100];
const UNIT = 'µg/m³';
const COLOR = 'orange';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;

const points = (refId) => {
  const frame = context.panel.data.series.find((f) => f.refId === refId);
  if (!frame) {
    return [];
  }
  const bins = frame.fields.find((f) => f.name === 'bin').values;
  const counts = frame.fields.find((f) => f.name === 'n').values;
  return Array.from(bins, (b, i) => [Number(b) + STEP / 2, Number(counts[i])]);
};
const all = points('all');
const selected = points('selected');
const domain = DOMAIN || [Math.min(...all.map((p) => p[0] - STEP / 2)), Math.max(...all.map((p) => p[0] + STEP / 2))];

// Whole bins only: a range that cuts a bar in two would count half of it.
const snap = (range) => {
  const lo = Math.floor(range[0] / STEP) * STEP;
  const hi = Math.max(Math.ceil(range[1] / STEP) * STEP, lo + STEP);
  return [lo, hi];
};
const drawBrush = (range) =>
  chart.dispatchAction({ type: 'brush', areas: range ? [{ brushType: 'lineX', xAxisIndex: 0, coordRange: range }] : [] });
const publish = (range) => {
  location.partial({ ['var-' + LO]: range ? String(range[0]) : '', ['var-' + HI]: range ? String(range[1]) : '' }, true);
};

chart.off('brushEnd');
chart.off('brush');
chart.on('brushEnd', (event) => {
  const area = event.areas[0];
  if (!area || !area.coordRange) {
    publish(undefined);
    return;
  }
  const range = snap(area.coordRange);
  publish(range);
  setTimeout(() => drawBrush(range), 0);
});
chart.on('brush', (event) => {
  if (event.command === 'clear') {
    publish(undefined);
  }
});

// Every redraw (setOption without merge) wipes the brush: draw it back from
// the variables, which is also how a shared link arrives with its range.
const current = [
  parseFloat(context.grafana.replaceVariables('${' + LO + '}')),
  parseFloat(context.grafana.replaceVariables('${' + HI + '}')),
];
setTimeout(() => {
  chart.dispatchAction({ type: 'takeGlobalCursor', key: 'brush', brushOption: { brushType: 'lineX', brushMode: 'single' } });
  if (current.every(Number.isFinite)) {
    drawBrush(current);
  }
}, 0);

const accent = theme.visualization.getColorByName(COLOR);
const muted = theme.colors.text.secondary;

return {
  animation: false,
  // The axis name sits under the axis labels, centred: at the end of the axis
  // it ran past the grid's right edge and was clipped ("ma" for magnitude).
  // `containLabel` leaves the name out, so `bottom` makes room for it.
  grid: { left: 8, right: 16, top: 30, bottom: 22, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'none' },
    formatter: (items) => {
      const x = items[0].value[0] - STEP / 2;
      const rows = items.map((it) => `${it.marker}${it.seriesName}: <b>${it.value[1]}</b>`).join('<br/>');
      return `${x}–${x + STEP} ${UNIT}<br/>${rows}`;
    },
  },
  toolbox: {
    right: 8,
    top: 0,
    itemSize: 14,
    feature: { brush: { type: ['lineX', 'clear'], title: { lineX: 'Select a range', clear: 'Clear the filter' } } },
  },
  brush: {
    xAxisIndex: 0,
    seriesIndex: [1],
    brushType: 'lineX',
    brushMode: 'single',
    transformable: true,
    brushStyle: { color: 'rgba(128, 128, 128, 0.12)', borderColor: muted, borderWidth: 1 },
    outOfBrush: { colorAlpha: 0.25 },
  },
  xAxis: { type: 'value', min: domain[0], max: domain[1], name: UNIT, nameLocation: 'middle', nameGap: 24, nameTextStyle: { color: muted }, axisLabel: { color: muted }, splitLine: { show: false } },
  yAxis: { type: 'value', axisLabel: { color: muted }, splitLine: { lineStyle: { opacity: 0.15 } } },
  series: [
    { name: 'All', type: 'bar', data: all, barWidth: '94%', silent: true, itemStyle: { color: 'rgba(128, 128, 128, 0.22)' } },
    { name: 'Filtered', type: 'bar', data: selected, barWidth: '94%', barGap: '-100%', itemStyle: { color: accent } },
  ],
};

// Countries ranked by their median sensor's 24-hour PM2.5, each bar in the
// colour of its WHO band. Clicking a bar picks that country alone in the
// Country picker at the top; clicking the only one picked goes back to All.
const VAR = 'country';
const BANDS = [15, 25, 37.5, 50, 75];
const COLORS = ['#4F8A9A', '#F2D16B', '#F0A04B', '#E5683C', '#C63A4A', '#8E2C6B'];

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;

const frame = context.panel.data.series[0];
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name).values) : []);
const codes = col('country');
const medians = col('median').map(Number);
const sensors = col('sensors').map(Number);

let names;
try {
  names = new Intl.DisplayNames(['en'], { type: 'region' });
} catch (e) {
  names = { of: (c) => c };
}
const label = (code) => {
  try {
    return names.of(code) || code;
  } catch (e) {
    return code;
  }
};
const band = (v) => BANDS.filter((b) => v > b).length;

// The codes picked, or none for All (whose value is '__all__').
const picked = () =>
  context.grafana
    .replaceVariables('${' + VAR + ':csv}')
    .split(',')
    .map((c) => c.replace(/'/g, '').trim())
    .filter((c) => c && c !== '__all__' && c !== '$__all');
const selected = picked();

// Highest at the top: a category axis draws its first item at the bottom.
const rows = codes.map((c, i) => ({ code: c, name: label(c), median: medians[i], sensors: sensors[i] })).reverse();

chart.off('click');
chart.on('click', (event) => {
  const code = rows[event.dataIndex].code;
  const now = picked();
  const alone = now.length === 1 && now[0] === code;
  location.partial({ ['var-' + VAR]: alone ? '$__all' : code }, true);
});

return {
  animation: false,
  grid: { left: 8, right: 48, top: 8, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'item',
    formatter: (it) => {
      const r = rows[it.dataIndex];
      const alone = selected.length === 1 && selected[0] === r.code;
      return `<b>${r.name}</b><br/>Median: <b>${r.median.toFixed(1)} µg/m³</b><br/>${r.sensors} sensors<br/><i>Click to ${alone ? 'go back to all countries' : 'pick it alone'}</i>`;
    },
  },
  xAxis: { type: 'value', axisLabel: { color: muted }, splitLine: { lineStyle: { opacity: 0.15 } } },
  yAxis: {
    type: 'category',
    data: rows.map((r) => r.name),
    axisTick: { show: false },
    axisLabel: { color: muted, width: 110, overflow: 'truncate', interval: 0, fontSize: 11 },
  },
  series: [
    {
      type: 'bar',
      barWidth: '70%',
      cursor: 'pointer',
      data: rows.map((r) => ({
        value: r.median,
        itemStyle: {
          color: COLORS[band(r.median)],
          opacity: selected.length && !selected.includes(r.code) ? 0.35 : 1,
          borderRadius: [0, 4, 4, 0],
        },
      })),
      label: { show: true, position: 'right', color: muted, formatter: (p) => p.value.toFixed(1) },
    },
  ],
};
